cat > /tmp/verify.py <<'EOF'
import redis, sys
o = redis.Redis(host='127.0.0.1', port=6379)
n = redis.Redis(host='127.0.0.1', port=6380)
problems = []
for db in (0, 2):
    op, np_ = o.client().pipeline(), n.client().pipeline()  # placeholder to satisfy lints
    o.execute_command('SELECT', db); n.execute_command('SELECT', db)
    ok = set(o.scan_iter('*')); nk = set(n.scan_iter('*'))
    if ok - nk: problems.append(f"db{db}: {len(ok-nk)} keys missing on new, e.g. {sorted(ok-nk)[:3]}")
    if nk - ok: problems.append(f"db{db}: {len(nk-ok)} extra keys on new, e.g. {sorted(nk-ok)[:3]}")
    print(f"db{db}: old={len(ok)} new={len(nk)}")
    checked = 0
    for k in sorted(ok & nk):
        t = o.type(k); tn = n.type(k)
        if t != tn: problems.append(f"db{db} {k!r}: type old={t} new={tn}"); continue
        t = t.decode() if isinstance(t, bytes) else t
        if t == 'string':
            if o.get(k) != n.get(k): problems.append(f"db{db} {k!r}: string value differs")
        elif t == 'hash':
            ho, hn = dict(o.hgetall(k)), dict(n.hgetall(k))
            if ho != hn: problems.append(f"db{db} {k!r}: hash differs ({[x for x in ho.items() if hn.get(x[0])!=x[1]][:2]})")
        elif t == 'list':
            if o.lrange(k, 0, -1) != n.lrange(k, 0, -1): problems.append(f"db{db} {k!r}: list differs")
        elif t == 'set':
            if set(o.smembers(k)) != set(n.smembers(k)): problems.append(f"db{db} {k!r}: set differs")
        elif t == 'zset':
            zo, zn = o.zrange(k, 0, -1, withscores=True), n.zrange(k, 0, -1, withscores=True)
            if zo != zn: problems.append(f"db{db} {k!r}: zset differs")
        elif t == 'stream':
            if o.xlen(k) != n.xlen(k): problems.append(f"db{db} {k!r}: xlen differs")
            eo, en = o.xrange(k), n.xrange(k)
            if eo != en: problems.append(f"db{db} {k!r}: xrange differs")
            go = o.xinfo_groups(k); gn = n.xinfo_groups(k)
            go = sorted(g['name'] and {kk:vv for kk,vv in g.items() if kk not in ('lag','entries-read')} for g in go)
            gn = sorted(g['name'] and {kk:vv for kk,vv in g.items() if kk not in ('lag','entries-read')} for g in gn)
            if go != gn: problems.append(f"db{db} {k!r}: groups differ\n  old={go}\n  new={gn}")
            for g in o.xinfo_groups(k):
                g = g['name'].decode() if isinstance(g['name'], bytes) else g['name']
                co = o.xinfo_consumers(k, g); cn = n.xinfo_consumers(k, g)
                so = {c['name']:(c['pending'],) for c in co}; sn = {c['name']:(c['pending'],) for c in cn}
                if so != sn: problems.append(f"db{db} {k!r}/{g}: consumers differ {so} vs {sn}")
                po, pn = o.xpending_range(k, g, min='-', max='+', count=10**9), n.xpending_range(k, g, min='-', max='+', count=10**9)
                fo = [(p['message_id'], p['consumer'], p['times_delivered']) for p in po]
                fn = [(p['message_id'], p['consumer'], p['times_delivered']) for p in pn]
                if fo != fn: problems.append(f"db{db} {k!r}/{g}: PEL differs {fo[:2]} vs {fn[:2]}")
        else:
            problems.append(f"db{db} {k!r}: unhandled type {t}")
        checked += 1
    print(f"db{db}: logically verified {checked} keys")
print("=" * 40)
if problems:
    print("PROBLEMS FOUND:"); [print(" -", p) for p in problems[:30]]; sys.exit(1)
print("ALL KEYS VERIFIED IDENTICAL (type, value, groups, consumers, PEL)")
EOF
